var hd = SugarCube.setup.help_data || {};
var lc = hd.locationCanvases || {};
var allIds = [];
var locKeys = Object.keys(lc);
for (var loc of locKeys) {
  if (Array.isArray(lc[loc])) {
    for (var c of lc[loc]) {
      allIds.push(c.id);
    }
  }
}
return JSON.stringify({
  help_data_keys: Object.keys(hd),
  locationCanvases_keys_count: locKeys.length,
  total_canvases: allIds.length,
  has_scene_livingroom_catch: allIds.includes('scene_livingroom_catch'),
  has_scene_franks_bedroom_evening: allIds.includes('scene_franks_bedroom_evening'),
  sample_ids: allIds.slice(0, 10),
  canvas_with_catch_substring: allIds.filter(id => id && id.toLowerCase().includes('catch'))
}, null, 2);

